        fn rate(&self) -> u64 {
            fetch_rate()
        }
    }
}

/// Composition layer (Net is allowed here): wires the live adapter into the
/// pure domain.
pub mod app {
    /// The top-level batch entry point (invoked by the scheduler, not from
    /// inside this crate). The rate is still genuinely fetched — by the
    /// adapter, outside the `domain` boundary — and the price is produced.
    pub fn run() -> u64 {
        crate::domain::run(&crate::infra::LiveRateSource)
    }
}
